package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.ChatFormatting;import net.minecraft.network.chat.CommonComponents;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.effect.MobEffect;import net.minecraft.world.effect.MobEffectInstance;import net.minecraft.world.item.alchemy.PotionUtils;import net.minecraftforge.registries.ForgeRegistries;import java.util.List;
public final class FoodTooltip{public static void appendMaxim(List<Component> lines,String key){if(key!=null)lines.add(Component.translatable(key).withStyle(ChatFormatting.DARK_GRAY,ChatFormatting.ITALIC));}public static void appendEffect(List<Component>lines,ResourceLocation id,int duration){if(id==null||duration<=0)return;MobEffect effect=ForgeRegistries.MOB_EFFECTS.getValue(id);if(effect==null)return;lines.add(CommonComponents.space());PotionUtils.addPotionTooltip(List.of(new MobEffectInstance(effect,duration)),lines,1.0F);}private FoodTooltip(){}}
